import { createSelector } from '@reduxjs/toolkit';
import { productsAdapter } from './productAdapter';

// Base adapter selectors generated by createEntityAdapter
export const {
  selectAll: selectAllProducts,
  selectById: selectProductById,
  selectIds: selectProductIds,
  selectEntities: selectProductEntities,
  selectTotal: selectProductTotalCount,
} = productsAdapter.getSelectors((state) => state.products);

// Status and Filter selectors
export const selectProductsStatus = (state) => state.products.status;
export const selectProductsError = (state) => state.products.error;
export const selectCategories = (state) => state.products.categories;
export const selectCategoriesStatus = (state) => state.products.categoriesStatus;
export const selectSelectedCategory = (state) => state.products.selectedCategory;
export const selectSearchTerm = (state) => state.products.searchTerm;
export const selectSortBy = (state) => state.products.sortBy;
export const selectPriceRange = (state) => state.products.priceRange;
export const selectMinRating = (state) => state.products.minRating;
export const selectSelectedProduct = (state) => state.products.selectedProduct;
export const selectProductDetailsStatus = (state) => state.products.productDetailsStatus;
export const selectProductDetailsError = (state) => state.products.productDetailsError;

/**
 * Memoized selector: Filtered products based on category, search term, price range, and min rating
 */
export const selectFilteredProducts = createSelector(
  [
    selectAllProducts,
    selectSelectedCategory,
    selectSearchTerm,
    selectPriceRange,
    selectMinRating,
  ],
  (products, category, searchTerm, priceRange, minRating) => {
    return products.filter((product) => {
      // Category filter
      const matchesCategory =
        !category ||
        category === 'all' ||
        product.category.toLowerCase() === category.toLowerCase();

      // Search term filter (title or description)
      const term = (searchTerm || '').trim().toLowerCase();
      const matchesSearch =
        !term ||
        product.title.toLowerCase().includes(term) ||
        product.description.toLowerCase().includes(term);

      // Price range filter
      const price = Number(product.price) || 0;
      const minPrice = priceRange ? priceRange[0] : 0;
      const maxPrice = priceRange ? priceRange[1] : 1000;
      const matchesPrice = price >= minPrice && price <= maxPrice;

      // Rating filter
      const rate = product.rating ? product.rating.rate : 0;
      const matchesRating = rate >= (minRating || 0);

      return matchesCategory && matchesSearch && matchesPrice && matchesRating;
    });
  }
);

/**
 * Memoized selector: Filtered and Sorted products
 */
export const selectFilteredAndSortedProducts = createSelector(
  [selectFilteredProducts, selectSortBy],
  (filteredProducts, sortBy) => {
    const list = [...filteredProducts];
    switch (sortBy) {
      case 'price-asc':
        return list.sort((a, b) => a.price - b.price);
      case 'price-desc':
        return list.sort((a, b) => b.price - a.price);
      case 'rating':
        return list.sort(
          (a, b) => (b.rating?.rate || 0) - (a.rating?.rate || 0)
        );
      case 'alpha-asc':
        return list.sort((a, b) => a.title.localeCompare(b.title));
      case 'alpha-desc':
        return list.sort((a, b) => b.title.localeCompare(a.title));
      case 'featured':
      default:
        return list;
    }
  }
);

/**
 * Memoized selector: Products for a specific category
 */
export const selectProductsByCategory = createSelector(
  [selectAllProducts, (_, category) => category],
  (products, category) => {
    if (!category || category === 'all') return products;
    return products.filter(
      (p) => p.category.toLowerCase() === category.toLowerCase()
    );
  }
);

/**
 * Memoized selector: Featured / Best Selling products (high rating & count)
 */
export const selectBestSellingProducts = createSelector(
  [selectAllProducts],
  (products) => {
    return [...products]
      .sort((a, b) => (b.rating?.count || 0) - (a.rating?.count || 0))
      .slice(0, 8);
  }
);

/**
 * Memoized selector: Trending products (high score rating)
 */
export const selectTrendingProducts = createSelector(
  [selectAllProducts],
  (products) => {
    return [...products]
      .sort((a, b) => (b.rating?.rate || 0) - (a.rating?.rate || 0))
      .slice(0, 8);
  }
);

/**
 * Memoized selector: New Arrivals (e.g. reverse order or curated)
 */
export const selectNewArrivals = createSelector(
  [selectAllProducts],
  (products) => {
    return [...products].reverse().slice(0, 8);
  }
);

/**
 * Memoized selector: Related products (same category, excluding current product)
 */
export const selectRelatedProducts = createSelector(
  [selectAllProducts, (_, currentProduct) => currentProduct],
  (products, currentProduct) => {
    if (!currentProduct) return [];
    return products
      .filter(
        (p) =>
          p.category.toLowerCase() === currentProduct.category?.toLowerCase() &&
          p.id !== currentProduct.id
      )
      .slice(0, 4);
  }
);
